// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"market-order":{"slug":"market-order","cat":"trading","en":"Market order","contentLocale":"en","term":"Market order","aka":["market buy","market sell"],"short":"A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price.","body":["When you place a market buy, the exchange matches it against the lowest asks until your size is filled. A market sell fills against the highest bids. You know the order will execute right away on a liquid pair, but you do not know the exact average price until it is done.",["Market orders remove ",["liquidity","liquidity"]," from the book, so they are charged the ",["taker fee","maker-taker-fees"],", which is usually higher than the maker fee. They also cross the ",["bid-ask spread","bid-ask-spread"]," and can suffer ",["slippage","slippage"]," if your order is large compared with the depth available."],["Use market orders when getting filled matters more than the exact price, such as closing a losing position quickly. For entries where you have time, a ",["limit order","limit-order"]," often gives a better price and a lower fee. Some exchanges add price protection that cancels the part of a market order that would fill too far from the reference price."]],"example":["Suppose SOL shows a best ask of 150.00 ",["USDT","usdt"]," and you market-buy 40 SOL. The book has 25 SOL at 150.00 and 30 SOL at 150.10, so you fill 25 at 150.00 and 15 at 150.10. You pay 3,750.00 + 2,251.50 = 6,001.50 USDT, an average of about 150.04. With a 0.1 percent taker fee you pay another 6.00 USDT. A limit order at 150.00 might have saved the extra 1.50 and part of the fee, but might not have filled fully."],"mistakes":["Using a market order on a low-liquidity coin and receiving a much worse average price.","Placing a market order during a fast spike and buying the very top.","Forgetting that market orders pay taker fees, which add up for frequent traders."],"faq":[{"q":"Is a market order or limit order better?","a":"A market order is better when you need to execute immediately. A limit order is better when price matters more and you can wait."},{"q":"Why did my market order fill at a different price?","a":"Because it filled against the available orders, which may be spread over several price levels, and the price can move between clicking and execution."},{"q":"Do market orders pay maker or taker fees?","a":"Taker fees, because they take liquidity from the order book."}],"title":"What is a market order in crypto? Meaning and example","description":"Learn how a crypto market order works, why it pays taker fees and when slippage makes it more expensive than expected.","related":[["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Market, limit, cancel: what does each one solve?"},"coin":null,"tool":null,"cta":true},"arbitrage":{"slug":"arbitrage","cat":"trading","en":"Arbitrage","contentLocale":"en","term":"Arbitrage","aka":["crypto arbitrage","arb"],"short":"Arbitrage is buying an asset where it is cheaper and selling it where it is more expensive at the same time, to profit from a price difference between markets.","body":[["Crypto trades on many exchanges at once, and prices are not always identical. If ",["BTC","bitcoin"]," is slightly cheaper on one venue than another, an arbitrageur buys on the cheaper one and sells on the more expensive one. Their trades push the prices back together, which helps keep markets consistent."],["There are several types. Spatial arbitrage uses price gaps between exchanges. Triangular arbitrage cycles through three pairs on one exchange, such as ",["USDT","usdt"]," to BTC to ",["ETH","ethereum"]," and back. ",["Funding rate","funding-rate"]," and basis arbitrage pair a spot position with a futures position to collect a funding payment or a price gap while staying market-neutral."],["Real-world arbitrage is harder than it looks. Trading fees, withdrawal fees, network confirmation times, deposit and withdrawal suspensions and ",["slippage","slippage"]," can wipe out a small gap. Professional firms keep funds on several exchanges in advance so they do not have to transfer during the trade. Regional price premiums can also persist for long periods because of capital controls."]],"example":"Suppose ETH trades at 3,000 USDT on exchange A and 3,018 on exchange B, a 0.6% gap. You hold funds on both and buy 2 ETH on A for 6,000 USDT while selling 2 ETH on B for 6,036 USDT. Gross profit is 36 USDT. With taker fees of 0.1% on each side, you pay about 6 + 6.04 = 12.04 USDT, leaving roughly 24 USDT. If you also had to withdraw ETH between venues, a network fee would cut that further.","mistakes":["Forgetting withdrawal fees and transfer time when the gap is only a fraction of a percent.","Assuming a price gap is free money when deposits or withdrawals are suspended on one side.","Leaving one leg of the trade open, which turns arbitrage into an ordinary directional bet."],"faq":[{"q":"Is crypto arbitrage still profitable?","a":"Large, easy gaps are rare on major pairs because many bots compete for them. Smaller opportunities exist, but costs and execution speed decide whether they are worth it."},{"q":"Is arbitrage risk-free?","a":"No. Execution delays, fee changes, frozen withdrawals and exchange risk can all turn an expected profit into a loss."}],"title":"What is arbitrage in crypto? How price gaps are traded","description":"Learn how crypto arbitrage works across exchanges, the main types, and the fees and risks that shrink real profits.","related":[["funding-rate-arbitrage","Funding rate arbitrage","Funding rate arbitrage is a market-neutral strategy that collects funding payments by holding opposite positions, usually spot long and perpetual short, so price moves largely cancel out."],["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment."],["market-maker","Market maker","A market maker is a trader or firm that continuously places both buy and sell orders on a market, providing liquidity and earning from the spread between them."],["withdrawal-fee","Withdrawal fee","A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"perpetual-futures":{"slug":"perpetual-futures","cat":"derivatives","en":"Perpetual futures (perps)","contentLocale":"en","term":"Perpetual futures (perps)","aka":["perps","perpetual swap","perpetual contract","perp"],"short":"Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price.","body":[["A normal ",["futures contract","futures-contract"]," expires, so its price naturally converges with spot at the end. A perpetual has no end date, so it needs another anchor. That anchor is the ",["funding rate","funding-rate"],": at set intervals, traders on one side pay traders on the other side."],["When the perp trades above the ",["index price","index-price"],", funding is usually positive and longs pay shorts, which encourages ",["shorting","short-selling"]," and pulls the price down. When it trades below, funding turns negative and shorts pay longs. Funding is commonly settled every 8 hours, but some exchanges and pairs use 1, 2 or 4 hours."],["Perps are the most traded crypto derivative. Centralized exchanges such as Binance, OKX, Bybit and Bitget list hundreds of them, and on-chain venues such as Hyperliquid offer perps too. You can hold a position as long as your margin covers losses and funding, but ",["liquidation","liquidation"]," is based on the ",["mark price","mark-price"],", not only the last traded price."]],"example":"Suppose you hold a 10,000 USDT long on a BTC perp and the funding rate is +0.01% per 8-hour interval. Each interval you pay 10,000 × 0.01% = 1 USDT to shorts, so 3 USDT a day and about 90 USDT over 30 days if the rate stayed unchanged. If funding flips to -0.02%, you would instead receive 2 USDT per interval while staying long.","mistakes":["Ignoring funding costs on a long-held leveraged position, where they can add up to a significant amount.","Assuming funding is always settled every 8 hours on every pair.","Watching only the last traded price when liquidation depends on the mark price."],"faq":[{"q":"Why are they called perpetual futures?","a":"Because they never expire. You can keep the position open indefinitely as long as you meet the margin requirements."},{"q":"Who pays the funding fee on perpetual futures?","a":"It depends on the sign of the rate. Positive funding means longs pay shorts, and negative funding means shorts pay longs. The exchange does not keep it."}],"title":"What are perpetual futures (perps)? Crypto explained","description":"Learn how perpetual futures work, why they never expire, how funding keeps them near spot and what that costs you.","related":[["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."],["mark-price","Mark price","The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["futures-contract","Futures contract","A futures contract is an agreement to buy or sell an asset at a set price in the future, which lets you trade price moves with margin and leverage without holding the asset itself."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":null,"tool":"/funding-rates","cta":true},"delivery-futures":{"slug":"delivery-futures","cat":"derivatives","en":"Delivery (quarterly) futures","contentLocale":"en","term":"Delivery (quarterly) futures","aka":["quarterly futures","dated futures","expiry futures","fixed-term futures"],"short":"Delivery futures are crypto futures contracts with a fixed expiry date, such as a weekly or quarterly contract, that settle at a set price when they expire.","body":[["Unlike ",["perpetual futures","perpetual-futures"],", a delivery ",["contract","smart-contract"]," has an end date written in its name, for example a ",["BTC","bitcoin"]," contract expiring at the end of a quarter. On that date the position closes automatically and settles. On most crypto exchanges settlement is in cash, using an average ",["index price","index-price"]," over a short window, rather than physical delivery of coins."],["Because there is a set expiry, there is no ",["funding rate","funding-rate"],". Instead, the contract usually trades at a premium or discount to spot, called the basis. In normal conditions longer-dated contracts trade at a premium, reflecting borrowing costs and demand for leveraged longs. As expiry approaches, that gap shrinks toward zero."],"Traders use delivery futures to lock in a price for a known date, to hedge, or to earn the basis by buying spot and selling the future. If you want to keep exposure after expiry, you must roll the position into the next contract, which can cost fees and a different basis. Expiry times and settlement rules differ by exchange."],"example":["Suppose BTC spot is 60,000 ",["USDT","usdt"]," and the quarterly contract expiring in 90 days trades at 61,200, a 2% premium. You buy 1 BTC spot and short 1 BTC of the quarterly contract. At expiry the future settles at the spot price. Whether BTC ends at 50,000 or 70,000, your combined position earns about the 1,200 USDT premium, roughly 2% over the quarter, before fees."],"mistakes":["Forgetting the expiry date and being surprised when the position settles automatically.","Assuming the futures price must equal spot before expiry.","Rolling into the next contract without checking how wide its premium is."],"faq":[{"q":"What happens when a crypto futures contract expires?","a":"The exchange closes all open positions at the settlement price, which is usually based on an index average shortly before expiry, and credits or debits your profit and loss."},{"q":"Do delivery futures have funding fees?","a":"No. They converge with spot through the expiry itself, so their price difference from spot shows up as a premium or discount instead."}],"title":"What are delivery (quarterly) futures in crypto?","description":"Learn how quarterly delivery futures work, how they settle at expiry and how they differ from perpetual futures.","related":[["futures-contract","Futures contract","A futures contract is an agreement to buy or sell an asset at a set price in the future, which lets you trade price moves with margin and leverage without holding the asset itself."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["futures-basis","Futures basis","The futures basis is the difference between a futures contract's price and the spot price of the same asset, often expressed as an annualised percentage."],["hedging","Hedging","Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":null,"tool":"/topics/derivatives","cta":false},"initial-margin":{"slug":"initial-margin","cat":"derivatives","en":"Initial margin","contentLocale":"en","term":"Initial margin","aka":["IM","opening margin"],"short":"Initial margin is the amount of collateral you must post to open a leveraged position, usually equal to the position value divided by your leverage.","body":[["When you open a futures or margin position, the exchange sets aside part of your balance as initial margin. At 10x ",["leverage","leverage"]," the initial margin rate is 10% of the position value; at 20x it is 5%. That is why higher leverage needs less margin for the same position."],["Initial margin is different from ",["maintenance margin","maintenance-margin"],". Initial margin is what you need to open the position. Maintenance margin is the lower level you must keep to avoid ",["liquidation","liquidation"],". The gap between the two is your buffer against adverse price moves."],["Exchanges often use risk tiers: the larger the position, the higher the initial margin rate, which lowers the maximum leverage available. Opening fees may also be reserved from your balance. With ",["isolated margin","isolated-margin"],", the initial margin is the most you can lose on that position; with ",["cross margin","cross-margin"],", losses can draw on the rest of your balance."]],"example":["Suppose you open a 0.5 ",["BTC","bitcoin"]," long at 60,000 USDT, a position worth 30,000 USDT, using 15x leverage. The initial margin is 30,000 ÷ 15 = 2,000 USDT. If you chose 5x instead, the same position would need 6,000 USDT of initial margin, but it would also sit much further from its liquidation price because the buffer above maintenance margin is larger."],"mistakes":["Thinking initial margin is the trade cost, when profit and loss are based on the full position value.","Confusing initial margin with maintenance margin.","Expecting maximum leverage on very large positions when risk tiers lower it."],"faq":[{"q":"How is initial margin calculated?","a":"In simple terms, position value divided by leverage. Exchanges may adjust it with risk tiers and may also hold back the estimated opening fee."},{"q":"Can I lose more than my initial margin?","a":"In isolated mode, your loss on that position is normally limited to its margin. In cross mode, losses can use your other available balance."}],"title":"What is initial margin in crypto futures? Explained","description":"Learn what initial margin is, how it is calculated from leverage and how it differs from maintenance margin in crypto futures.","related":[["maintenance-margin","Maintenance margin","Maintenance margin is the minimum collateral you must keep in a leveraged position; if your margin falls below it, the position is liquidated."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."],["isolated-margin","Isolated margin","Isolated margin is a margin mode where each position has its own separate collateral, so a liquidation can only take the margin assigned to that position."],["margin-trading","Margin trading","Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Why you can be closed out before your margin hits zero"},"coin":null,"tool":null,"cta":false},"portfolio-margin":{"slug":"portfolio-margin","cat":"derivatives","en":"Portfolio margin","contentLocale":"en","term":"Portfolio margin","aka":["PM","portfolio margin mode"],"short":"Portfolio margin is a margin system that sets your collateral requirement based on the combined risk of all your positions, so hedged positions need less margin than they would separately.","body":[["Standard margin looks at each position, or each asset, on its own. Portfolio margin runs scenarios across your whole account, for example moving prices and ",["volatility","volatility"]," up and down by set amounts, and asks how much the entire portfolio could lose. Your requirement is based on that worst-case result."],["If you hold offsetting positions, such as spot ",["BTC","bitcoin"]," and a BTC short perpetual, or options hedged with futures, the losses in one scenario are partly cancelled by gains in another. Portfolio margin recognises that, so you need less collateral and can use capital more efficiently."],["It is aimed at advanced traders. Exchanges such as Binance, OKX, Bybit and Deribit offer portfolio margin modes, often with minimum account sizes, eligibility checks or limits on which assets qualify. The lower margin can also mean higher effective ",["leverage","leverage"],", so a portfolio that is not truly hedged can be liquidated quickly. Methods and requirements differ by exchange."]],"example":["Suppose you hold 2 BTC spot and short 2 BTC on a perpetual at 60,000 ",["USDT","usdt"],". Under standard rules the short might need, say, 10% margin, or 12,000 USDT, on its own. Under portfolio margin, a 15% price drop would lose 18,000 USDT on the spot side but gain about 18,000 on the short. The net scenario loss is close to zero, so the requirement might be only a small fraction of 12,000 USDT, depending on the exchange's model."],"mistakes":["Assuming any mix of positions is hedged, when correlations can break in a crash.","Using the freed-up margin to add unhedged risk.","Ignoring that the exchange can change scenario parameters and raise margin requirements."],"faq":[{"q":"What is the difference between cross margin and portfolio margin?","a":"Cross margin shares one balance across positions but usually sums each position's requirement. Portfolio margin goes further and nets out offsetting risk between positions."},{"q":"Who should use portfolio margin?","a":"Experienced traders running hedged strategies, options books or basis trades. For simple directional trading it adds complexity without much benefit."}],"title":"What is portfolio margin in crypto? Explained","description":"Learn how portfolio margin calculates requirements across your whole account, why hedges need less margin and the risks.","related":[["cross-margin","Cross margin","Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation."],["isolated-margin","Isolated margin","Isolated margin is a margin mode where each position has its own separate collateral, so a liquidation can only take the margin assigned to that position."],["unified-trading-account","Unified trading account (UTA)","A unified trading account (UTA) is an exchange account mode that lets you trade spot, margin, futures and sometimes options from one balance, with assets shared as collateral."],["hedging","Hedging","Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Cross margin: why one loss can hit your other positions"},"coin":null,"tool":null,"cta":false},"short-squeeze":{"slug":"short-squeeze","cat":"derivatives","en":"Short squeeze","contentLocale":"en","term":"Short squeeze","aka":["squeeze","short liquidation cascade"],"short":"A short squeeze is a rapid price rise that forces short sellers to buy back their positions, through stop-losses or liquidation, which pushes the price even higher.","body":[["When many traders are short and the price starts to rise, their losses grow. To close a short, they must buy. Stop-losses trigger, ",["liquidation","liquidation"]," engines close leveraged shorts with market buys, and that extra buying pushes the price further, triggering more short exits."],["Squeezes are more likely when ",["open interest","open-interest"]," is high, funding is deeply negative because shorts are paying longs, and the coin has thin ",["liquidity","liquidity"],". A piece of good news or a large buyer can be enough to start the chain. The mirror case, a long squeeze, forces leveraged longs to sell into a falling market."],["For a short seller, the lesson is ",["position size","position-sizing"]," and stops. For anyone else, a squeeze can create sharp, short-lived moves that reverse once the forced buying is done. Chasing a squeeze near its peak often means buying just as the forced buying runs out."]],"example":["Suppose a token trades at 1.00 ",["USDT","usdt"]," with 50 million USDT of open interest, mostly shorts, and funding at -0.1% per 8 hours. Positive news pushes price to 1.08. Shorts opened at 1.00 with 10x ",["leverage","leverage"]," start getting liquidated near 1.09, adding market buys. Price spikes to 1.35 within an hour, then slides back to 1.15 once liquidations stop and open interest has dropped to 30 million USDT."],"mistakes":["Opening a large leveraged short on a heavily shorted, thin coin.","Buying at the peak of a squeeze, assuming the move reflects lasting demand.","Ignoring deeply negative funding, which signals how crowded the short side is."],"faq":[{"q":"What causes a short squeeze in crypto?","a":"A rise in price when many leveraged shorts are open. Their stop-losses and liquidations turn into market buys, which feed the rise."},{"q":"How can you spot a possible short squeeze?","a":"Look for high open interest, negative funding and thin liquidity together. These signs show crowding, not timing."}],"title":"What is a short squeeze in crypto? How it happens","description":"Learn what a short squeeze is, how liquidations of leveraged shorts fuel it and the warning signs traders watch.","related":[["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["short-selling","Short selling","Short selling is a way to profit from a falling price by selling an asset you have borrowed, or opening a short contract, and buying it back later at a lower price."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."],["open-interest","Open interest","Open interest is the total number or value of derivatives contracts, such as futures or options, that are currently open and not yet closed or settled."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"usdc":{"slug":"usdc","cat":"stablecoins","en":"USDC","contentLocale":"en","term":"USDC","aka":["USD Coin","Circle USDC"],"short":"USDC is a US dollar stablecoin issued by Circle, designed to stay at 1 dollar and backed by cash and short-term US government securities, with monthly reserve attestations.","body":[["USDC runs on many blockchains, including ",["Ethereum","ethereum"],", Solana, Base, Arbitrum, Polygon and others. Circle's Cross-Chain Transfer Protocol (CCTP) lets USDC move between supported chains by burning it on one chain and minting it on another, instead of creating wrapped copies."],["Circle publishes monthly attestations of its reserves, which are held largely in cash and a government ",["money market","defi-lending"]," fund. Like ",["USDT","usdt"],", USDC can be frozen at specific addresses. In the EU, Circle operates under ",["MiCA","mica"]," authorisation, which makes USDC widely available on EU-regulated platforms."],"USDC is not immune to depegs. In March 2023, it briefly traded well below 1 dollar after part of its reserves was held at Silicon Valley Bank, which failed. It returned to its peg once the deposits were secured."],"example":["Suppose you want to move 3,000 USDC from Ethereum to Base. Through a bridge that uses CCTP, the 3,000 USDC is burned on Ethereum and 3,000 native USDC is minted on Base, minus network fees. If you used a bridge that issues a wrapped version, you might receive a token that some Base apps treat as a different asset. During the 2023 ",["depeg","depeg"],", if USDC briefly traded at 0.90 dollars, those 3,000 USDC would have been priced at about 2,700 dollars on the market."],"mistakes":["Assuming bridged USDC and native USDC on the same chain are always interchangeable.","Believing USDC cannot depeg because it is regulated.","Sending USDC on a network the receiving exchange does not list for USDC deposits."],"faq":[{"q":"Is USDC safer than USDT?","a":"They have different risk profiles. USDC publishes monthly attestations and is authorised under MiCA, while USDT has larger liquidity on many exchanges. Both carry issuer and freeze risk."},{"q":"Who issues USDC?","a":"Circle issues USDC and manages its reserves."}],"title":"What is USDC? Circle's dollar stablecoin explained","description":"What USDC is, how Circle backs it, how native USDC moves across chains, and why even USDC briefly lost its peg.","related":[["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["usdt","USDT (Tether)","USDT, also called Tether, is the largest US dollar stablecoin, issued by Tether, designed to stay at 1 dollar and backed by reserves the company reports in regular attestations."],["depeg","Depeg","A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD."],["mica","MiCA (EU Markets in Crypto-Assets)","MiCA (Markets in Crypto-Assets) is the European Union regulation that sets common rules for crypto-asset issuers, stablecoins and crypto service providers across all EU member states."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Is USDT a dollar? Why is it everywhere when you buy crypto?"},"coin":{"slug":"usdc","name":"USDC","symbol":"USDC"},"tool":null,"cta":false},"launchpool":{"slug":"launchpool","cat":"exchange-features","en":"Launchpool","contentLocale":"en","term":"Launchpool","aka":["launch pool","token farming pool"],"short":"A Launchpool is an exchange program where you lock tokens you already hold, such as the exchange token or a stablecoin, for a set period to earn a new token before or around its listing.","body":[["Binance Launchpool popularised the format, and other exchanges run similar programs under different names. Each campaign lists eligible ",["staking","staking"]," assets, a total reward pool and a duration. Rewards are usually calculated hourly based on your share of the total staked amount and credited to your account."],"Your staked tokens stay yours and can usually be withdrawn at any time, though you stop earning once they leave the pool. The real cost is price risk on what you stake: if you buy an exchange token just to join, a drop in its price can outweigh the rewards.",["Rewards are often small for each participant because many users stake. Most programs require ",["KYC","kyc"]," and are not available in every country. Per-user caps, eligibility rules and reward schedules vary, so read each campaign's rules before staking."]],"example":["Suppose a campaign distributes 3,000,000 new tokens over 10 days, so 300,000 per day. You stake 2,000 ",["USDT","usdt"]," in a pool that holds 400,000,000 USDT in total. Your share is 2,000 divided by 400,000,000, which is 0.0005%. That earns you 1.5 tokens per day, or 15 tokens over 10 days. If the token lists at 0.40 USDT, your reward is worth about 6 USDT."],"mistakes":["Buying a volatile exchange token only to join a Launchpool without considering its price risk.","Expecting the advertised total rewards to translate into large personal earnings.","Missing that rewards stop accruing as soon as you unstake."],"faq":[{"q":"Is Launchpool free money?","a":"There is no direct fee, but the assets you stake carry price risk and rewards depend on your share of the pool. Many users earn modest amounts."},{"q":"What is the difference between Launchpool and Launchpad?","a":"In a Launchpool you stake tokens to earn a new token for free. In a Launchpad you commit funds to buy a new token in a sale."}],"title":"What is a Launchpool? Earning new tokens by staking","description":"What a Launchpool is, how staking for new tokens works, how rewards are calculated and how it differs from a Launchpad sale.","related":[["launchpad","Launchpad (token sale)","A launchpad is a platform, often run by an exchange, where users can buy a new project's tokens in a sale before or as the tokens list for trading."],["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["airdrop","Airdrop","An airdrop is a distribution of free tokens to wallet addresses or exchange users, usually to reward early users, decentralize ownership or promote a new project."],["token-listing","Token listing","A token listing is when an exchange adds a coin to its markets, letting users deposit, trade and withdraw it on that platform."]],"lesson":null,"coin":null,"tool":"/activities","cta":true}});
